package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamPhysicsElecBank1 {
  private const val T = "විද්‍යුතය, ගෘහස්ථ පරිපථ, චුම්භකත්වය හා ඉලෙක්ට්‍රොනික විද්‍යාව"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "විද්‍යුතය, චුම්භකත්වය හා ඉලෙක්ට්‍රොනික විද්‍යාවට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("විද්‍යුත් ආරෝපණයේ අන්තර්ජාතික SI ඒකකය කුමක්ද?", "කූලොම්බ් (C)", "ඇම්පියර් (A)", "වෝල්ට් (V)", "ඕම් (Ω)", "ඉලෙක්ට්‍රෝනයක ආරෝපණය 1.6 × 10⁻¹⁹ C වේ."),
    q("සිල්ක් රෙදි කැබැල්ලකින් වීදුරු දණ්ඩක් පිරිමැද්ද විට වීදුරු දණ්ඩට ලැබෙන්නේ කුමන ස්ථිති විද්‍යුත් ආරෝපණයක්ද?", "ධන ආරෝපණයක් (+)", "සෘණ ආරෝපණයක් (-)", "උදාසීන වේ", "චුම්භක ධ්‍රැවයක්", "වීදුරු දණ්ඩෙන් ඉලෙක්ට්‍රෝන සිල්ක් රෙද්දට මාරු වන බැවින් සිල්ක් සෘණ ආරෝපිත වේ."),
    q("ස්ථිති විද්‍යුත් නියමයට අනුව සජාතීය ආරෝපණ (+ හා +) සහ විජාතීය ආරෝපණ (+ හා -) අතර සිදු වන්නේ කුමක්ද?", "සජාතීය විකර්ෂණය වේ; විජාතීය ආකර්ෂණය වේ", "සජාතීය ආකර්ෂණය වේ; විජාතීය විකර්ෂණය වේ", "ආරෝපණ වර්ග දෙකම එකිනෙක විකර්ෂණය වේ", "ආරෝපණ අතර කිසිදු විද්‍යුත් බලයක් නැත", "වස්තුවක් ආරෝපිත දැයි පරීක්ෂා කිරීමට ස්වර්ණ පත්‍ර විද්‍යුත් දර්ශකය භාවිත කෙරේ."),
    q("අකුණු සන්නායකයක් (Lightning conductor) උස් ගොඩනැගිලි මුදුනේ සවි කර පොළොවට සම්බන්ධ කිරීමේ ප්‍රධාන අරමුණ කුමක්ද?", "ආරෝපණ ආරක්ෂිතව පොළොවට බැහැර කිරීම", "වළාකුළු තුළ නව අකුණු විදුලිය නිපදවීම", "ගොඩනැගිල්ල අවට වර්ෂාපතනය වැඩි කිරීම", "ගොඩනැගිල්ලේ ගෘහස්ථ විදුලිය ඉතිරි කිරීම", "තඹ පටියක් මගින් ධාරාව පොළොවට ගෙන යයි."),
    q("තත්පර 10 ක් තුළ සන්නායකයක හරස්කඩක් හරහා 50 C ක විද්‍යුත් ආරෝපණයක් ගලා ගියහොත් ගලන විද්‍යුත් ධාරාව කීයද?", "5 A", "500 A", "0.2 A", "40 A", "I = Q / t = 50 / 10 = 5 A."),
    q("පරිපථයක අග්‍ර දෙක අතර විභව අන්තරය මැනීම සඳහා වෝල්ට්මීටරය සම්බන්ධ කළ යුත්තේ කෙසේද?", "අග්‍ර දෙකට සමාන්තරගතව (Parallel)", "පරිපථයට ශ්‍රේණිගතව (Series)", "බැටරිය ඉවත් කර", "භූගත වයරයට පමණක්", "ඇමීටරය ධාරාව මැනීමට ශ්‍රේණිගතව ද වෝල්ට්මීටරය සමාන්තරගතව ද සවි කෙරේ."),
    q("නියත උෂ්ණත්වයකදී සන්නායකයක් තුළින් ගලන විද්‍යුත් ධාරාව (I) එහි අග්‍ර දෙක අතර විභව අන්තරයට (V) අනුලෝමව සමානුපාතික බව පවසන නියමය කුමක්ද?", "ඕම්ගේ නියමය (Ohm's law)", "කූලොම්බ් නියමය", "ෆැරඩේ නියමය", "ලෙන්ස් නියමය", "V = IR; නියත උෂ්ණත්වයේදී V-I ප්‍රස්තාරය මූල ලක්ෂ්‍යය හරහා යන සෘජු රේඛාවකි."),
    q("12 V බැටරියකට 4 Ω ප්‍රතිරෝධකයක් සම්බන්ධ කළ විට පරිපථයේ ගලන ධාරාව කීයද?", "3 A", "48 A", "0.33 A", "16 A", "I = V / R = 12 / 4 = 3 A."),
    q("6 Ω සහ 3 Ω ප්‍රතිරෝධක දෙකක් ශ්‍රේණිගතව (Series) සම්බන්ධ කළ විට ලැබෙන සමක ප්‍රතිරෝධය කීයද?", "9 Ω", "2 Ω", "18 Ω", "3 Ω", "ශ්‍රේණිගත විට R = R₁ + R₂ = 6 + 3 = 9 Ω."),
    q("6 Ω සහ 3 Ω ප්‍රතිරෝධක දෙකක් සමාන්තරගතව (Parallel) සම්බන්ධ කළ විට ලැබෙන සමක ප්‍රතිරෝධය කීයද?", "2 Ω", "9 Ω", "4.5 Ω", "18 Ω", "1/R = 1/6 + 1/3 = 3/6 = 1/2 → R = 2 Ω."),
    q("නිවසේ විදුලි පරිපථවල සියලු විදුලි බුබුළු හා පේනු කෙවෙනි සමාන්තරගතව (Parallel) සම්බන්ධ කර ඇත්තේ ඇයි?", "සැමට 230 V ලැබීම හා ස්වාධීනව ක්‍රියා කිරීම", "පරිපථයේ මුළු විද්‍යුත් ධාරාව අඩු කර ගැනීම", "පරිපථයේ සමක ප්‍රතිරෝධය දස ගුණයක් කිරීම", "සම්බන්ධක තඹ කම්බි දිග කෙටි කර ගැනීම", "තවද එක් එක් උපකරණය වෙන වෙනම ස්විච් මගින් පාලනය කළ හැක."),
    q("ලෝහ කම්බියක දිග දෙගුණ කර හරස්කඩ වර්ගඵලය අඩකින් අඩු කළහොත් එහි විද්‍යුත් ප්‍රතිරෝධයට කුමක් සිදුවේද?", "හතර ගුණයකින් (4×) වැඩි වේ", "වෙනස් නොවේ", "දෙගුණ වේ", "අඩකින් අඩු වේ", "R = ρL / A නිසා දිග 2× හා A ½ විට R අගය 4 ගුණයක් වේ."),
    q("230 V, 1150 W ලෙස සඳහන් විදුලි ඉස්තිරික්කයක් ක්‍රියාත්මක වන විට එය ඇද ගන්නා විදුලි ධාරාව කීයද?", "5 A", "0.2 A", "10 A", "2.5 A", "P = VI → I = P / V = 1150 / 230 = 5 A."),
    q("230 V, 1000 W විදුලි හීටරයක් පැය 3 ක් දැල්වූ විට වැය වන විදුලි ඒකක (kWh) ගණන කීයද?", "3 ඒකක (3 kWh)", "3000 ඒකක", "0.3 ඒකක", "30 ඒකක", "1000 W = 1 kW; ශක්තිය = 1 kW × 3 h = 3 kWh."),
    q("ගෘහස්ථ විදුලි පරිපථයක විද්‍යුත් සැර වැදීමෙන් ආරක්ෂා වීමට මිලිඇම්පියර් 30 ක පමණ කාන්දු ධාරාවකදී පවා ස්වයංක්‍රීයව විදුලිය විසන්ධි කරන උපකරණය කුමක්ද?", "ශේෂ ධාරා පරිපථ බිඳිනය", "කිලෝවොට් පැය විදුලි මීටරය", "සාමාන්‍ය විභවමාන වෝල්ට්මීටරය", "අර්ධ සන්නායක සිලිකන් ඩයෝඩය", "සජීවී හා උදාසීන කම්බිවල ධාරා වෙනසක් ඇති වූ විගස RCCB ක්‍රියාත්මක වේ."),
    q("ගෘහස්ථ පරිපථයක 'සජීවී' (Live), 'උදාසීන' (Neutral) සහ 'භූගත' (Earth) කම්බිවල අන්තර්ජාතික වර්ණ කේත පිළිවෙළින් මොනවාද?", "දුඹුරු, නිල් සහ කොළ/කහ", "කොළ, රතු සහ කළු", "නිල්, දුඹුරු සහ සුදු", "රතු, කොළ සහ නිල්", "සෑම විටම ස්විච හා විලායක (Fuses) සවි කළ යුත්තේ සජීවී (දුඹුරු) කම්බියටය."),
    q("විදුලි ප්ලග් එකක හා රෙදි මදින ඉස්තිරික්කයේ ලෝහ ආවරණය භූගත (Earth) කම්බියට සම්බන්ධ කරන්නේ ඇයි?", "ධාරා කාන්දුව පොළොවට යවා විදුලි සැර වැළැක්වීම", "ඉස්තිරික්කයේ තාපන දඟරය ඉක්මනින් රත් කිරීම", "ගෘහස්ථ මාසික විදුලි බිල්පත අඩු කර ගැනීම", "උපකරණයේ ක්‍රියාකාරී උෂ්ණත්වය පාලනය කිරීම", "තෙවන (විශාල) ඇණය Earth සඳහා වන අතර එය මුලින්ම සම්බන්ධ වේ."),
    q("විද්‍යුත් තාපන උපකරණවල (උදා: විදුලි කේතල, හීටර්) තාපන දඟරය සෑදීමට තඹ වෙනුවට 'නික්‍රෝම්' (Nichrome) යොදා ගන්නේ ඇයි?", "ඉහළ ප්‍රතිරෝධකතාවක් සහ ඉහළ උෂ්ණත්වයේදී ඔක්සිකරණය නොවී පැවතීම නිසා", "නික්‍රෝම් ප්‍රතිරෝධය ශුන්‍ය නිසා", "නික්‍රෝම් 100°C දී දිය වන නිසා", "නික්‍රෝම් පරිවාරකයක් නිසා", "H = I²Rt අනුව වැඩි ප්‍රතිරෝධයක් ඇති විට වැඩි තාපයක් ජනනය වේ."),
    q("සජීවී විද්‍යුත් ධාරාවක් ගෙන යන සෘජු කම්බියක් වටා ඇතිවන චුම්භක ක්ෂේත්‍රයේ හැඩය හා දිශාව සොයන නීතිය කුමක්ද?", "ඒකකේන්ද්‍රීය වෘත්ත; දකුණත් ග්‍රහණ නියමය", "සමාන්තර සෘජු රේඛා; ෆැරඩේගේ ප්‍රේරණ නියමය", "සර්පිලාකාර රේඛා; ෆ්ලෙමිංගේ වමත් නියමය", "අක්ෂීය රේඛා; සාමාන්‍ය ඕම්ගේ විදුලි නියමය", "දකුණතේ මහපටැඟිල්ල ධාරා දිශාවට යොමු කළ විට අනෙක් ඇඟිලි නැමෙන දිශාව චුම්භක ක්ෂේත්‍ර දිශාවයි."),
    q("විද්‍යුත් චුම්භකයක් (Electromagnet) සෑදීමේදී පරිවාරක තඹ කම්බි දඟරය ඇතුළට 'මෘදු යකඩ' (Soft iron) හරයක් දමන්නේ ඇයි?", "ප්‍රබලව චුම්භකනය වී ධාරාව නැවැත්වූ විට මැකීම", "මෘදු යකඩ සෑමවිටම ස්ථිර චුම්භකයක් බවට පත්වීම", "දඟරය හරහා විදුලි ධාරාව ගලා යාම වැළැක්වීම", "විදුලි දඟරය අධිකව රත් වීම සම්පූර්ණයෙන් නැවැත්වීම", "වානේ භාවිත කළහොත් ධාරාව නැවැත්වූ පසුවත් ස්ථිර චුම්භකත්වය රැඳී පවතී."),
    q("විදුලි මෝටරයක් (DC motor) ක්‍රියා කරන මූලික භෞතික විද්‍යා මූලධර්මය කුමක්ද?", "චුම්භක ක්ෂේත්‍රයක ධාරා සන්නායකය මත බලය යෙදීම", "සංවෘත දඟරයක සිදුවන විද්‍යුත් චුම්භක ප්‍රේරණය", "අධි ධාරාවක් නිසා ඇතිවන රේඛීය තාප ප්‍රසාරණය", "ප්‍රතිවිරුද්ධ ආරෝපණ අතර ස්ථිති විද්‍යුත් බලය", "මෝටරයක බල දිශාව සොයන්නේ ෆ්ලෙමිංගේ වමත් නියමය (Fleming's Left-Hand Rule) මගිනි."),
    q("DC මෝටරයක දඟරය නොකඩවා එකම දිශාවට කරකැවීම සඳහා සෑම අර්ධ වටයකට වරක් ධාරාවේ දිශාව ආපසු හරවන උපාංගය කුමක්ද?", "විභේදක වළලු කොමියුටේටරය", "සම්පූර්ණ ලිස්සන වළලු දෙක", "විද්‍යුත් ධාරා විලායකය", "ධාරා වර්ධක ට්‍රාන්සිස්ටරය", "කාබන් බුරුසු ස්පර්ශ කරමින් දෙපළු වළල්ල ධාරා දිශාව මාරු කරයි."),
    q("චුම්භකයක් කම්බි දඟරයක් තුළට වේගයෙන් ඇතුළු කිරීමේදී හෝ පිටතට ගැනීමේදී දඟරයේ විභව අන්තරයක් හට ගැනීම හඳුන්වන්නේ කෙසේද?", "විද්‍යුත් චුම්භක ප්‍රේරණය", "ස්ථිති විද්‍යුත් ප්‍රේරණය", "ද්‍රාවණ විද්‍යුත් විච්ඡේදනය", "සන්නායක තාප සන්නයනය", "මයිකල් ෆැරඩේ විසින් මෙම නියමය සොයා ගත් අතර විදුලි ජනක යන්ත්‍ර මින් ක්‍රියා කරයි."),
    q("ප්‍රත්‍යාවර්ත ධාරා (AC) ඩයිනමෝවක හා සරල ධාරා (DC) මෝටරයක ශක්ති පරිවර්තන පිළිවෙළින් මොනවාද?", "යාන්ත්‍රික → විද්‍යුත් සහ විද්‍යුත් → යාන්ත්‍රික", "විද්‍යුත් → යාන්ත්‍රික සහ යාන්ත්‍රික → විද්‍යුත්", "රසායනික → විද්‍යුත් සහ විද්‍යුත් → රසායනික", "තාප → විද්‍යුත් සහ විද්‍යුත් → ආලෝක ශක්ති", "AC ජනකයේ ලිස්සන වළලු (Slip rings) දෙකක් භාවිත කෙරේ."),
    q("ප්‍රේරිත විද්‍යුත් ගාමක බලයේ විශාලත්වය වැඩි කිරීම සඳහා ඩයිනමෝවක කළ නොහැකි දෙය කුමක්ද?", "දඟරය කරකැවීම නැවැත්වීම", "දඟරයේ පොට ගණන වැඩි කිරීම", "වඩා ශක්තිමත් චුම්භකයක් භාවිත කිරීම", "භ්‍රමණ වේගය වැඩි කිරීම", "චුම්භක ස්‍රාවය වෙනස් වීමේ සීඝ්‍රතාව ශුන්‍ය වූ විට ප්‍රේරිත ධාරාව ශුන්‍ය වේ."),
    q("පරිණාමකයක් (Transformer) ක්‍රියාත්මක කළ හැක්කේ කුමන ආකාරයේ විදුලි සැපයුමකින් පමණද?", "ප්‍රත්‍යාවර්ත ධාරා (AC) සැපයුමකින් පමණි", "සරල ධාරා (DC) බැටරියකින් පමණි", "ස්ථිති විද්‍යුතයෙන්", "ඕනෑම බැටරියකින්", "ප්‍රාථමික දඟරයේ වෙනස් වන චුම්භක ක්ෂේත්‍රයක් සෑදීමට AC අවශ්‍ය වේ."),
    q("අවකර පරිණාමකයක (Step-down transformer) ප්‍රාථමික දඟරයේ පොට 1000 ක් සහ ද්විතීයික දඟරයේ පොට 100 ක් ඇත. ප්‍රාථමිකයට 230 V AC ලබා දුන්නොත් ද්විතීයික වෝල්ටීයතාව කීයද?", "23 V", "2,300 V", "230 V", "115 V", "Vₛ / Vₚ = Nₛ / Nₚ → Vₛ = 230 × (100 / 1000) = 23 V."),
    q("ජල විදුලි බලාගාරවල සිට ඉතා දුර නගරවලට විදුලිය සම්ප්‍රේෂණය කිරීමේදී අධික වෝල්ටීයතාවයකට (උදා: 132 kV) නංවා යවන්නේ ඇයි?", "ධාරාව අඩු කර රැහැන්වල I²R තාප හානිය අවම කිරීමට", "සම්ප්‍රේෂණ කම්බිවල විද්‍යුත් ප්‍රතිරෝධය වැඩි කිරීමට", "ජාතික පද්ධතිය තුළ විදුලි ශක්තිය ගබඩා කර තැබීමට", "නිවාසවලට 132 kV වෝල්ටීයතාව කෙළින්ම සැපයීමට", "P = VI නිසා V ඉතා වැඩි කළ විට I කුඩා වී තාප හානිය විශාල ලෙස අඩු වේ."),
    q("ශ්‍රී ලංකාවේ ජාතික විදුලිබල පද්ධතියෙන් නිවසට ලබා දෙන AC විදුලි සැපයුමේ සංඛ්‍යාතය හා වෝල්ටීයතාව කොපමණද?", "50 Hz, 230 V", "60 Hz, 110 V", "50 Hz, 12 V", "100 Hz, 400 V", "AC ධාරාව තත්පරයකට 50 වතාවක් සම්පූර්ණ චක්‍ර සිදු කරමින් දිශාව මාරු කරයි."),
    q("පිරිසිදු සිලිකන් (Si) අර්ධ සන්නායකයකට පොස්පරස් (V කාණ්ඩය) වැනි මූලද්‍රව්‍යයක් මාත්‍රණය (Doping) කළ විට සෑදෙන අර්ධ සන්නායක වර්ගය කුමක්ද?", "n-වර්ගයේ අර්ධ සන්නායකය", "p-වර්ගයේ අර්ධ සන්නායකය", "සුපිරි විද්‍යුත් පරිවාරකය", "ධන සෘණ අයනික ස්ඵටිකය", "බෝරෝන් හෝ ඇලුමිනියම් (III කාණ්ඩය) මාත්‍රණය කළ විට කුහර බහුල p-වර්ගය සෑදේ."),
    q("p-n සන්ධි ඩයෝඩයක (Diode) ප්‍රධානතම ඉලෙක්ට්‍රොනික කාර්යය කුමක්ද?", "ධාරාව එක් දිශාවකට පමණක් යැවීම (ඍජුකරණය)", "දුර්වල ප්‍රත්‍යාවර්ත ධාරාවක් වර්ධනය කිරීම", "විද්‍යුත් ආරෝපණ දිගු කාලයක් ගබඩා කිරීම", "සැපයුම් වෝල්ටීයතාව දස ගුණයකින් ඉහළ නැංවීම", "ඉදිරි නැඹුරු (Forward bias) විට සන්නයනය කරන අතර පසු නැඹුරු විට අවහිර කරයි."),
    q("ප්‍රත්‍යාවර්ත ධාරාවක් (AC) සරල ධාරාවක් (DC) බවට පරිවර්තනය කිරීමේ ක්‍රියාවලිය හඳුන්වන්නේ කෙසේද?", "ඍජුකරණය (Rectification)", "වර්ධනය", "ප්‍රේරණය", "විඝටනය", "දුරකථන චාජර තුළ ඩයෝඩ 4 ක පූර්ණ තරංග සේතු ඍජුකාරකය හා සුමටන ධාරිත්‍රකයක් ඇත."),
    q("පූර්ණ තරංග ඍජුකාරකයකින් ලැබෙන ස්පන්දන DC වෝල්ටීයතාව සුමට (Smooth) ස්ථිර DC බවට පත් කිරීමට සමාන්තරගතව යොදන උපාංගය කුමක්ද?", "ධාරිත්‍රකය (Capacitor)", "ප්‍රේරකය", "විලායකය", "LDR එක", "ධාරිත්‍රකය ආරෝපණය ගබඩා කර වෝල්ටීයතාව පහළ බසින විට මුදා හරී."),
    q("විදුලි ධාරාවක් ගලා ගිය විට ආලෝකය නිකුත් කරන p-n සන්ධි උපාංගය කුමක්ද?", "LED (ආලෝක විමෝචක ඩයෝඩය)", "Zener ඩයෝඩය", "LDR", "තර්මිස්ටරය", "LED ඉතා අඩු විදුලියකින් ඉහළ කාර්යක්ෂමතාවයකින් ආලෝකය ලබා දේ."),
    q("ආලෝකය වැඩි වන විට ප්‍රතිරෝධය අඩු වන, ස්වයංක්‍රීය වීදි ලාම්පු පාලන පරිපථවල භාවිත කරන සංවේදකය කුමක්ද?", "ආලෝක සංවේදී ප්‍රතිරෝධකය (LDR)", "තර්මිස්ටරය", "ඩයෝඩය", "වෝල්ට්මීටරය", "රාත්‍රී අඳුරේදී LDR හි ප්‍රතිරෝධය ඉතා ඉහළ යන නිසා පහන දැල්වීමට සංඥාවක් සපයයි."),
    q("NPN ට්‍රාන්සිස්ටරයක අග්‍ර තුන හඳුන්වන නිවැරදි නාම මොනවාද?", "පාදම, සංග්‍රාහකය සහ විමෝචකය", "ඇනෝඩය, කැතෝඩය සහ ග්‍රිඩ් අග්‍රය", "සජීවී, උදාසීන සහ භූගත අග්‍ර", "ධන, සෘණ සහ මධ්‍යම අග්‍ර", "ට්‍රාන්සිස්ටරයක් ඉලෙක්ට්‍රොනික ස්විචයක් හා ධාරා වර්ධකයක් (Amplifier) ලෙස ක්‍රියා කරයි."),
    q("තර්ක ද්වාර (Logic gates) අතුරින් ආදාන දෙකම '1' (HIGH) වූ විට පමණක් ප්‍රතිදානය '1' ලබා දෙන තර්ක ද්වාරය කුමක්ද?", "AND ද්වාරය", "OR ද්වාරය", "NOT ද්වාරය", "NAND ද්වාරය", "AND ද්වාරයේ සත්‍යතා වගුව අනුව 1·1 = 1 ද අනෙක් සියල්ල 0 ද වේ."),
    q("ආදානය '1' නම් ප්‍රතිදානය '0' ද, ආදානය '0' නම් ප්‍රතිදානය '1' ද ලබා දෙන තනි ආදාන තර්ක ද්වාරය කුමක්ද?", "NOT ද්වාරය (Inverter)", "AND ද්වාරය", "OR ද්වාරය", "NOR ද්වාරය", "NOT ද්වාරය ආදාන තත්ත්වය ප්‍රතිලෝම කරයි."),
    q("ආදාන දෙකෙන් අවම වශයෙන් එකක් හෝ '1' වූ විට ප්‍රතිදානය '1' ලබා දෙන තර්ක ද්වාරය කුමක්ද?", "OR ද්වාරය", "AND ද්වාරය", "NAND ද්වාරය", "NOR ද්වාරය", "OR ද්වාරයේ 0+0=0 වන අතර 1+0, 0+1, 1+1 යන සියල්ලට 1 ලැබේ."),
    q("ස්ථිර චුම්භකයක් හරි මැදින් දෙකට කැඩුවහොත් ලැබෙන කැබලි දෙක කෙබඳු වේද?", "සෑම කැබැල්ලක්ම උතුරු හා දකුණු ධ්‍රැව දෙකම දරයි", "එක් කැබැල්ලක තනි උතුරු ධ්‍රැවයක් පමණක් පවතී", "කැබලි දෙකේම චුම්භකත්වය සම්පූර්ණයෙන් නැති වේ", "කැබලි දෙකම අචුම්භක ප්ලාස්ටික් බවට පත් වේ", "තනි චුම්භක ධ්‍රැවයක් (Monopole) කිසිදා පැවතිය නොහැක."),
    q("දණ්ඩ චුම්භකයකින් පිටතදී චුම්භක බල රේඛා ගමන් කරන දිශාව කුමක්ද?", "උතුරු ධ්‍රැවයේ සිට දකුණු ධ්‍රැවයට", "දකුණු ධ්‍රැවයේ සිට උතුරු ධ්‍රැවයට", "චුම්භකයේ මැද සිට පිටත දිශාවට", "චුම්භක අක්ෂයට සමාන්තරව පමණි", "චුම්භකය ඇතුළතදී බල රේඛා S සිට N දක්වා ගොස් සංවෘත පුඩු සාදයි."),
    q("පෘථිවියේ චුම්භක ක්ෂේත්‍රය නිසා නිදහසේ එල්ලන ලද දණ්ඩ චුම්භකයක් සැමවිටම හැරී සිටින්නේ කුමන දිශාවටද?", "භූගෝලීය උතුරු-දකුණු දිශාවට", "නැගෙනහිර-බටහිර දිශාවට", "සිරස්ව ඉහළට", "45° ඇලව", "මාලිමාව නාවික හා ගවේෂණ කටයුතුවලට භාවිත කරන්නේ මෙම ගුණය නිසාය."),
    q("පහත දැක්වෙන ද්‍රව්‍ය අතුරින් චුම්භකයකට ප්‍රබලව ආකර්ෂණය නොවන (අචුම්භක) ද්‍රව්‍යය කුමක්ද?", "තඹ හා ඇලුමිනියම්", "යකඩ", "නිකල්", "කොබෝල්ට්", "යකඩ, වානේ, නිකල් හා කොබෝල්ට් ප්‍රබල ෆෙරෝචුම්භක ද්‍රව්‍ය වේ."),
    q("සෝලා පැනලයක් (Solar cell) මගින් සිදු කරන ප්‍රධාන ශක්ති පරිවර්තනය කුමක්ද?", "සූර්ය ආලෝක ශක්තිය → විද්‍යුත් ශක්තිය", "සූර්ය තාප ශක්තිය → යාන්ත්‍රික ශක්තිය", "රසායනික ශක්තිය → ආලෝක ශක්තිය", "විද්‍යුත් ශක්තිය → න්‍යෂ්ටික ශක්තිය", "සූර්ය කෝෂ සෑදී ඇත්තේ p-n සන්ධි සිලිකන් අර්ධ සන්නායක මගිනි."),
    q("10 Ω ප්‍රතිරෝධයක් තුළින් 2 A ධාරාවක් තත්පර 60 ක් ගලා ගියහොත් නිපදවෙන තාප ශක්තිය කීයද?", "2,400 J", "1,200 J", "200 J", "400 J", "H = I²Rt = 2² × 10 × 60 = 4 × 10 × 60 = 2,400 J."),
    q("පරිපථයක ශ්‍රේණිගතව ඇති 2 Ω, 3 Ω හා 5 Ω ප්‍රතිරෝධක තුන 20 V බැටරියකට සම්බන්ධ කර ඇත. 5 Ω ප්‍රතිරෝධකය හරහා විභව අන්තරය කීයද?", "10 V", "20 V", "4 V", "6 V", "මුළු R = 2+3+5 = 10 Ω; I = 20/10 = 2 A; V₅ = 2 × 5 = 10 V."),
    q("වෝල්ට්මීටරයක අභ්‍යන්තර ප්‍රතිරෝධය කෙබඳු විය යුතුද?", "අතිශයින්ම ඉහළ (අනන්තයට ආසන්න)", "ශුන්‍යය", "1 Ω ට අඩු", "10 Ω", "පරිපථයෙන් ඉතාම අල්ප ධාරාවක් පමණක් වෝල්ට්මීටරය තුළට ගැනීමට මෙය අවශ්‍ය වේ."),
    q("ඇමීටරයක අභ්‍යන්තර ප්‍රතිරෝධය ඉතා කුඩා (ශුන්‍යයට ආසන්න) විය යුත්තේ ඇයි?", "ධාරාව වෙනස් නොකර නිවැරදිව මැනීමට", "පරිපථය හරහා විදුලිය ගැලීම අවහිර කිරීමට", "පරිපථයේ විභව අන්තරය දෙගුණ කිරීමට", "පරිපථය තුළ අමතර තාපයක් නිපදවීමට", "ඉහළ ප්‍රතිරෝධයක් තිබුණහොත් පරිපථයේ ධාරාව අඩු වී වැරදි පාඨාංක ලැබේ."),
    q("230 V ගෘහස්ථ විදුලි පරිපථයකට 2000 W ක ඉහළ ක්ෂමතා විදුලි අවන් එකක් සම්බන්ධ කිරීම සඳහා තෝරා ගත යුතු සුදුසුම විලායක අගය (Fuse rating) කුමක්ද?", "13 A", "3 A", "5 A", "1 A", "I = 2000 / 230 ≈ 8.7 A බැවින් ඊට මඳක් වැඩි සම්මත 13 A විලායකයක් සුදුසුය."),
    q("2 A ධාරාවක් තත්පර 30 ක් තිස්සේ සන්නායකයක් හරහා ගලා යන විට ගමන් කළ මුළු විද්‍යුත් ආරෝපණය කීයද?", "60 C", "15 C", "0.067 C", "32 C", "Q = I × t = 2 × 30 = 60 C."),
    q("පරිපථයක 4 V විභව අන්තරයක් හරහා 50 C ආරෝපණයක් ගෙන යන විට වැය වන විද්‍යුත් ශක්තිය කීයද?", "200 J", "12.5 J", "54 J", "400 J", "W = V × Q = 4 × 50 = 200 J."),
    q("10 Ω ප්‍රතිරෝධක දෙකක් ශ්‍රේණිගතව සම්බන්ධ කළ විට සමක ප්‍රතිරෝධය කීයද?", "20 Ω", "5 Ω", "10 Ω", "100 Ω", "ශ්‍රේණිගත පරිපථයේදී R = R₁ + R₂ = 10 + 10 = 20 Ω."),
    q("10 Ω ප්‍රතිරෝධක දෙකක් සමාන්තරගතව සම්බන්ධ කළ විට සමක ප්‍රතිරෝධය කීයද?", "5 Ω", "20 Ω", "10 Ω", "2.5 Ω", "1/R = 1/10 + 1/10 = 2/10 → R = 5 Ω."),
    q("2 Ω, 4 Ω සහ 6 Ω ප්‍රතිරෝධක තුනක් ශ්‍රේණිගතව සම්බන්ධ කළ විට ලැබෙන මුළු ප්‍රතිරෝධය කීයද?", "12 Ω", "1.09 Ω", "6 Ω", "24 Ω", "R = 2 + 4 + 6 = 12 Ω."),
    q("විදුලි පරිපථයක 3 V කෝෂ දෙකක් සමාන්තරගතව සම්බන්ධ කළ විට සංයුක්ත කෝෂ පද්ධතියේ විද්‍යුත් ගාමක බලය කීයද?", "3 V", "6 V", "1.5 V", "9 V", "සමාන්තරගතව සම්බන්ධ කළ සමාන කෝෂවල වෝල්ටීයතාව නොවෙනස්ව පවතී."),
    q("කිසියම් සන්නායකයක දිග වැඩි වන විට එහි විද්‍යුත් ප්‍රතිරෝධය කෙසේ වෙනස් වේද?", "අනුලෝමව වැඩි වේ", "අඩු වේ", "වෙනස් නොවේ", "ශුන්‍ය වේ", "R ∝ L (නියත උෂ්ණත්වයේදී හා ඒකාකාර හරස්කඩක් ඇති විට)."),
    q("කම්බියක හරස්කඩ වර්ගඵලය (ඝනකම) වැඩි වන විට එහි විද්‍යුත් ප්‍රතිරෝධයට කුමක් සිදුවේද?", "ප්‍රතිරෝධය අඩු වේ", "ප්‍රතිරෝධය වැඩි වේ", "වෙනස් නොවේ", "දෙගුණ වේ", "ප්‍රතිරෝධය හරස්කඩ වර්ගඵලයට ප්‍රතිලෝමව සමානුපාතික (R ∝ 1/A) වේ."),
    q("තඹ සහ කොන්ස්ටන්ටන් කම්බි අතුරින් විද්‍යුත් ධාරාව සම්ප්‍රේෂණය කිරීමේ රැහැන් සෑදීමට තඹ තෝරා ගන්නේ ඇයි?", "තඹවල ප්‍රතිරෝධකතාව ඉතා අඩු බැවිනි", "තඹ ඉතා ඉහළ ප්‍රතිරෝධයක් දරන නිසාය", "තඹ යනු විද්‍යුත් පරිවාරකයක් නිසාය", "තඹ අඩු උෂ්ණත්වයේදී දියවන නිසාය", "අඩු ප්‍රතිරෝධය නිසා සම්ප්‍රේෂණ තාප හානිය අවම වේ."),
    q("60 W විදුලි පහනක් 240 V සැපයුමකට සම්බන්ධ කළ විට එය හරහා ගලන ධාරාව කීයද?", "0.25 A", "4 A", "14,400 A", "60 A", "I = P / V = 60 / 240 = 0.25 A."),
    q("5 Ω ප්‍රතිරෝධයක් තුළින් 3 A ධාරාවක් ගලන විට එහි ජනනය වන විද්‍යුත් ක්ෂමතාව කීයද?", "45 W", "15 W", "75 W", "9 W", "P = I²R = 3² × 5 = 9 × 5 = 45 W."),
    q("2 kW විදුලි ගීසරයක් දිනකට පැය 2 බැගින් දින 10 ක් භාවිත කළහොත් වැය වන විදුලි ඒකක ගණන කීයද?", "40 ඒකක (40 kWh)", "20 kWh", "4 kWh", "200 kWh", "E = 2 kW × (2 × 10) h = 2 × 20 = 40 kWh."),
